<?php namespace App; use Illuminate\Database\Eloquent\Model; class MedicalCertificate extends Model {protected $guarded=[];protected $dates=['issue_date','valid_from','valid_until','issued_at','cancelled_at'];public function patient(){return $this->belongsTo(Patient::class);}public function consultation(){return $this->belongsTo(Consultation::class);}public function doctor(){return $this->belongsTo(User::class,'issued_by_doctor_id');}}
